#include <iostream>
#include <vector>

using namespace std;

/**
 * Problem: 2015-03 - Sudoku
 * 
 * 解題思路：
 * 1. 使用標準的回溯法 (Backtracking) 來填寫數獨。
 * 2. 對於每個空格 (0)，嘗試填入 1 到 9。
 * 3. 檢查填入的數字是否符合數獨規則：
 *    - 同一行不重複。
 *    - 同一列不重複。
 *    - 同一個 3x3 九宮格內不重複。
 * 4. 如果找到解，則輸出解；如果嘗試所有可能性都無法解出，則輸出 "NO"。
 */

int board[9][9];

bool isValid(int r, int c, int val) {
    for (int i = 0; i < 9; i++) if (board[r][i] == val) return false;
    for (int i = 0; i < 9; i++) if (board[i][c] == val) return false;
    int startR = (r / 3) * 3;
    int startC = (c / 3) * 3;
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (board[startR + i][startC + j] == val) return false;
    return true;
}

bool solve() {
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            if (board[r][c] == 0) {
                for (int val = 1; val <= 9; val++) {
                    if (isValid(r, c, val)) {
                        board[r][c] = val;
                        if (solve()) return true;
                        board[r][c] = 0;
                    }
                }
                return false;
            }
        }
    }
    return true;
}

int main() {
    int n;
    if (!(cin >> n)) return 0;
    while (n--) {
        for (int i = 0; i < 9; i++)
            for (int j = 0; j < 9; j++)
                cin >> board[i][j];

        if (solve()) {
            for (int i = 0; i < 9; i++) {
                for (int j = 0; j < 9; j++) {
                    cout << board[i][j] << (j == 8 ? "" : " ");
                }
                cout << endl;
            }
        } else {
            cout << "NO" << endl;
        }
    }
    return 0;
}
